grammar:[
 GR("Imperativ mit du und Sie","الأمر مع du و Sie",`<p>Mit dem Imperativ gibst du Tipps und Anweisungen.</p><div class="gt-wrap"><table class="gt"><tr><th>Verb</th><th>du-Form</th><th>Sie-Form</th></tr><tr><td>trinken</td><td>Trink viel!</td><td>Trinken Sie viel!</td></tr><tr><td>bleiben</td><td>Bleib im Bett!</td><td>Bleiben Sie im Bett!</td></tr><tr><td>nehmen</td><td>Nimm die Tablette!</td><td>Nehmen Sie die Tablette!</td></tr></table></div><p>Bei <b>du</b> fällt das „” und das „” weg: du trinkst → Trink!</p>`),
 GR("Modalverben: sollen, müssen, dürfen","الأفعال الناقصة: sollen و müssen و dürfen",`<p><b>müssen</b> = لازم (ضروري) · <b>sollen</b> = المفروض (نصيحة) · <b>dürfen</b> = مسموح. Das zweite Verb steht am Ende (Satzklammer).</p><div class="exbox">Du <b>musst</b> viel trinken.<br>Du <b>sollst</b> zum Arzt gehen.<br>Du <b>darfst</b> nicht rauchen.</div><div class="gt-wrap"><table class="gt"><tr><th></th><th>müssen</th><th>sollen</th><th>dürfen</th></tr><tr><td>ich</td><td>muss</td><td>soll</td><td>darf</td></tr><tr><td>du</td><td>musst</td><td>sollst</td><td>darfst</td></tr><tr><td>er/sie</td><td>muss</td><td>soll</td><td>darf</td></tr></table></div>`),
 GR("Aussprache: p/b, t/d, k/g","النطق: p/b و t/d و k/g",`<p>Diese Paare sind ähnlich. <b>p, t, k</b> sind hart und ohne Stimme; <b>b, d, g</b> sind weich und mit Stimme.</p><div class="exbox"><b>p</b> wie in „” ↔ <b>b</b> wie in „”<br><b>t</b> wie in „” ↔ <b>d</b> wie in „”<br><b>k</b> wie in „” ↔ <b>g</b> wie in „”</div><p>Am Wortende klingt <b>b, d, g</b> oft hart: „” → „”.</p>`)
],
