readings:[READ("Anzeige","Eine neue Wohnung",
 "Lena sucht eine Wohnung in Köln. Sie liest eine Anzeige: Schöne, helle Wohnung mit drei Zimmern, Küche und Balkon. Die Miete ist nicht zu teuer. Lena ruft an und besucht die Wohnung. Das Wohnzimmer ist groß und gemütlich. In der Küche gibt es einen neuen Kühlschrank. Das Schlafzimmer ist klein, aber hell. Die Wohnung gefällt Lena sehr und sie sagt: Ich nehme die Wohnung!",
 "لينا بتدوّر على شقة في كولونيا. بتقرأ إعلان: شقة حلوة منوّرة، 3 أوض ومطبخ وبلكونة، والإيجار مش غالي. بتتصل وبتزور الشقة. غرفة المعيشة كبيرة ومريحة، والمطبخ فيه تلاجة جديدة. غرفة النوم صغيرة بس منوّرة. الشقة عجباها أوي وقالت: هاخد الشقة!",
 [["suchen","يدوّر على"],["die Miete","الإيجار"],["der Kühlschrank","التلاجة"]],
 [["Wo sucht Lena eine Wohnung?","In Köln."],["Wie viele Zimmer hat die Wohnung?","Drei Zimmer."],["Wie ist das Schlafzimmer?","Klein, aber hell."]])],
grammar:[
 GR("Wechselpräpositionen: wo? und wohin?","حروف الجر المتغيرة: فين؟ وعلى فين؟",`<p>Diese Präpositionen (in, an, auf, über, unter, neben, vor, hinter, zwischen) haben zwei Fälle:</p><div class="gt-wrap"><table class="gt"><tr><th>Frage</th><th>Fall</th><th>Beispiel</th></tr><tr><td>Wo? (Ort, ثابت)</td><td>Dativ</td><td>Das Sofa steht <b>in dem (im)</b> Wohnzimmer.</td></tr><tr><td>Wohin? (حركة)</td><td>Akkusativ</td><td>Ich stelle das Sofa <b>in das (ins)</b> Wohnzimmer.</td></tr></table></div><p>Bewegung → Akkusativ, Position → Dativ.</p>`),
 GR("sein + Adjektiv","الفعل sein + صفة",`<p>Mit <b>sein</b> beschreibst du Dinge. Das Adjektiv bleibt gleich.</p><div class="exbox">Die Wohnung <b>ist</b> hell.<br>Das Zimmer <b>ist</b> klein, aber gemütlich.<br>Die Möbel <b>sind</b> neu.</div>`),
 GR("Aussprache: langes und kurzes e","النطق: e الطويلة والقصيرة",`<p>Das <b>e</b> kann lang oder kurz sein:</p><div class="gt-wrap"><table class="gt"><tr><th>langes e (إيه طويلة)</th><th>kurzes e (إيه قصيرة)</th></tr><tr><td>der See, gehen</td><td>das Bett, hell</td></tr><tr><td>der Tee, lesen</td><td>der Schrank? nein → das Fenster</td></tr></table></div><p>Vor zwei Konsonanten ist das e meist kurz: B<b>e</b>tt, h<b>e</b>ll.</p>`)
],
