readings:[READ("Bericht","Mein erster Arbeitstag",
 "Sami hat eine neue Stelle in einer Firma gefunden. Er erzählt: Gestern war mein erster Arbeitstag. Ich bin um sieben Uhr aufgestanden und habe schnell gefrühstückt. Dann bin ich mit dem Bus zur Arbeit gefahren. Im Büro habe ich meine Kollegen kennengelernt und viele E-Mails gelesen. Am Mittag haben wir zusammen gegessen. Der Tag hat mir gut gefallen und ich bin glücklich nach Hause gekommen.",
 "سامي لقى وظيفة جديدة في شركة. بيحكي: إمبارح كان أول يوم شغل. صحيت الساعة 7 وفطرت بسرعة. بعدها ركبت الأتوبيس للشغل. في المكتب اتعرّفت على زمايلي وقريت إيميلات كتير. الظهر أكلنا مع بعض. اليوم عجبني وروّحت البيت مبسوط.",
 [["finden / gefunden","يلاقي / لقى"],["aufstehen / aufgestanden","يصحى / صحى"],["kennenlernen","يتعرّف على"]],
 [["Was hat Sami gefunden?","Eine neue Stelle."],["Wie ist er zur Arbeit gefahren?","Mit dem Bus."],["Wie war der Tag?","Der Tag hat ihm gut gefallen."]])],
grammar:[
 GR("Perfekt: haben/sein + Partizip II","الماضي: haben/sein + التصريف الثالث",`<p>Das Perfekt benutzt man zum Erzählen von der Vergangenheit. Du brauchst <b>haben</b> oder <b>sein</b> + Partizip II. Das Partizip steht am <b>Ende</b> (Satzklammer).</p><div class="exbox">Ich <b>habe</b> E-Mails <b>gelesen</b>.<br>Ich <b>bin</b> nach Hause <b>gekommen</b>.</div><p>Verben der <b>Bewegung</b> (gehen, kommen, fahren) und der <b>Veränderung</b> nehmen <b>sein</b>. Die meisten anderen nehmen <b>haben</b>.</p>`),
 GR("Partizip II bilden","تكوين التصريف الثالث (Partizip II)",`<div class="gt-wrap"><table class="gt"><tr><th>Typ</th><th>Infinitiv</th><th>Partizip II</th></tr><tr><td>regelmäßig</td><td>machen</td><td>ge<b>macht</b></td></tr><tr><td>regelmäßig</td><td>arbeiten</td><td>ge<b>arbeitet</b></td></tr><tr><td>unregelmäßig</td><td>lesen</td><td>ge<b>lesen</b></td></tr><tr><td>unregelmäßig</td><td>kommen</td><td>ge<b>kommen</b></td></tr><tr><td>auf -ieren</td><td>studieren</td><td>studier<b>t</b> (ohne ge-)</td></tr></table></div>`),
 GR("Aussprache: das h","النطق: حرف h",`<p>Am Wortanfang spricht man <b>h</b> mit Luft (مهموس): <b>H</b>aus, <b>h</b>aben, <b>h</b>eute.</p><p>Nach einem Vokal ist das <b>h</b> oft stumm und macht den Vokal lang: ge<b>h</b>en, se<b>h</b>en, Ja<b>h</b>r → الـ h مبتتنطقش بس بتطوّل الحرف.</p>`)
],
